    updated_at timestamp with time zone NOT NULL,
    numero_serie integer NOT NULL,
    repetitions_prevues integer NOT NULL,
    poids_prevu double precision NOT NULL,
    repos_prevu integer NOT NULL,
    repetitions_realisees integer NOT NULL,
    poids_utilise double precision,
    statut character varying(15) NOT NULL,
    duree_serie integer,
    frequence_cardiaque_apres integer,
    note_effort integer,
    commentaire text NOT NULL,
    exercice_id bigint NOT NULL,
    duree_prevue integer,
    duree_realisee integer,
    CONSTRAINT workouts_seriexercice_duree_prevue_check CHECK ((duree_prevue >= 0)),
    CONSTRAINT workouts_seriexercice_duree_realisee_check CHECK ((duree_realisee >= 0)),
    CONSTRAINT workouts_seriexercice_duree_serie_check CHECK ((duree_serie >= 0)),
    CONSTRAINT workouts_seriexercice_frequence_cardiaque_apres_check CHECK ((frequence_cardiaque_apres >= 0)),
    CONSTRAINT workouts_seriexercice_note_effort_check CHECK ((note_effort >= 0)),
    CONSTRAINT workouts_seriexercice_numero_serie_check CHECK ((numero_serie >= 0)),
    CONSTRAINT workouts_seriexercice_repetitions_prevues_check CHECK ((repetitions_prevues >= 0)),
    CONSTRAINT workouts_seriexercice_repetitions_realisees_check CHECK ((repetitions_realisees >= 0)),
    CONSTRAINT workouts_seriexercice_repos_prevu_check CHECK ((repos_prevu >= 0))
);


