21	2025-07-11 21:05:02.638326+00	2025-07-29 20:50:57.251101+00	t	\N	Abdominal Crunch		Installez-vous dans la machine à abdominaux, le dos appuyé contre le dossier.\r\nCoincez vos pieds sous les boudins.\r\nSaisissez les poignées de chaque côté de votre tête.\r\nExpirez en contractant vos abdominaux pour plier votre abdomen et votre bassin de manière à tirer les poignées vers le bas et le boudin cale-pied vers le haut.\r\nInspirez en relâchant les abdos et le bassin pour revenir à la position de départ.\r\nRépétez le mouvement jusqu’à effectuer le nombre de répétitions prévues.	- Réglez la hauteur du siège de la machine pour un confort et une amplitude de mouvement optimale.\r\n- Maintenez votre dos fermement appuyé contre le dossier.\r\n- Gardez votre cou dans une position neutre : ne forcez pas avec votre cou.\r\n\r\n!! Si vous ne réussissez pas à effectuer un crunch avec une amplitude de mouvement complète, c’est peut-être que vous utilisez une charge trop lourde.\r\n!! Ne tirez pas vers le bas avec vos bras ; gardez-les fixes. Tout le mouvement doit être effectué par la flexion de vos abdominaux.	2.5	0	200	DEBUTANT	0	t	f						0		0	0	1	REPETITIONS	https://res.cloudinary.com/dnernoibr/image/upload/v1752751075/basicfit/machines/gifs/machine_crunch-machine-abdominaux.gif		3-1-1
28	2025-07-12 11:33:58.934204+00	2025-07-21 10:50:55.061713+00	t	\N	Cable Crunch		Créée automatiquement depuis import CLe Cable Crunch est un exercice d’isolation qui cible principalement les muscles abdominaux, en particulier le grand droit de l’abdomen (les "tablettes de chocolat"). Il se réalise en position agenouillée, à l’aide d’une poulie haute et d’une corde.\r\n\r\nMuscles ciblés :\r\n\r\nPrincipal : Grand droit de l’abdomen\r\n\r\nSecondaires : Obliques internes (selon la technique)	Installation :\r\nRègle la poulie en position haute.\r\nAccroche une corde à la poulie.\r\nAgenouille-toi face à la machine, à une distance d’environ 50 cm.\r\nSaisis la corde avec les deux mains et place-la derrière ta tête (ou à côté des tempes).\r\n\r\nPosition de départ :\r\nDos droit, bassin stable, genoux au sol.\r\nGarde les bras fixes (les coudes ne doivent pas tirer la charge).\r\nEngage les abdos.\r\n\r\nExécution du crunch :\r\nEnroule le buste vers le bas en contractant les abdominaux.\r\nAmène le front vers les genoux, sans tirer avec les bras.\r\nGarde les hanches fixes (pas de flexion de hanche, seulement flexion de la colonne).\r\n\r\nRetour contrôlé :\r\nRemonte lentement à la position de départ sans relâcher complètement la tension.\r\nNe laisse pas la charge tirer ton dos vers l’arrière.	2.5	0	200	DEBUTANT	0	t	f						0		0	0	1	REPETITIONS	https://res.cloudinary.com/dnernoibr/image/upload/v1752751873/basicfit/machines/gifs/machine_5468d5032b585e2e6682f9257d27d568.gif		
