38	2025-07-14 08:42:44.072864+00	2025-07-17 11:59:36.035692+00	t	\N	Cable Fly		Le Cable Fly est un exercice d’isolation qui cible principalement les pectoraux, en particulier la portion interne du grand pectoral. Contrairement au développé, il n’implique pas fortement les triceps ou les deltoïdes antérieurs.\r\n\r\nType d’exercice : Isolation\r\n\r\nMuscle principal : Grand pectoral (surtout la partie sternale et interne)\r\n\r\nMuscles secondaires : Deltoïdes antérieurs, biceps (stabilisateurs)	Réglages :\r\n\r\nRégle les poulies à hauteur d’épaule (ou un peu au-dessus).\r\n\r\nFixe une poignée à chaque câble.\r\n\r\nPrends une poignée dans chaque main, bras ouverts, légèrement fléchis (position en "cœur").\r\n\r\nPosition de départ :\r\n\r\nDebout, un pied légèrement en avant (position de fente pour stabilité).\r\n\r\nBuste droit, légère inclinaison vers l’avant (environ 15°).\r\n\r\nBras écartés, coudes légèrement fléchis (comme si tu allais enlacer un arbre).\r\n\r\nExécution du fly :\r\n\r\nAmène les poignées l’une vers l’autre, en arc de cercle, devant ta poitrine.\r\n\r\nContracte fortement les pectoraux en fin de mouvement.\r\n\r\nGarde les bras semi-fléchis tout au long du mouvement.\r\n\r\nRetour contrôlé :\r\n\r\nOuvre lentement les bras pour revenir à la position de départ.\r\n\r\nGarde la tension dans les pectoraux.\r\n\r\nRépétitions :\r\n\r\n3–4 séries de 12–15 répétitions (parfait pour finition ou hypertrophie)	2.5	0	200	DEBUTANT	0	t	f						0		0	0	1	REPETITIONS	https://res.cloudinary.com/dnernoibr/image/upload/v1752753575/basicfit/machines/gifs/machine_2424e53f9fe58cd08960fda5c653be2c.gif		
33	2025-07-13 07:04:26.982094+00	2025-07-18 06:22:19.630998+00	t	\N	Rameur		Le rameur simule l’action d’un rameur d’aviron : tu pousses avec les jambes, puis tires avec les bras pour ramener la poignée vers le ventre, avant de revenir à la position de départ.	1. Asseyez-vous et attachez vos pieds\r\n2. Saisissez la poignée, dos droit\r\n3. Commencez par pousser avec les jambes\r\n4. Puis tirez avec le dos et les bras\r\n5. Revenez en sens inverse : bras, dos, jambes\r\n6. Gardez un mouvement fluide et contrôlé	2.5	0	200	INTERMEDIAIRE	70	t	f						0	cardio,rameur,complet,intermediaire	0	0	3	DUREE	https://res.cloudinary.com/dnernoibr/image/upload/v1752781986/basicfit/machines/gifs/machine_rameur.gif		2-0-1
