27	2025-07-11 21:05:03.26178+00	2025-07-17 12:58:56.221606+00	t	\N	Cable Glute Pull-Through		Le Cable Glute Pull-Through est un exercice polyarticulaire qui cible principalement les fessiers et les ischio-jambiers, tout en engageant le tronc. Il simule un hip hinge (charnière de hanche) comme le deadlift roumain, mais avec résistance vers l’arrière au lieu du bas.\r\n\r\nMuscles ciblés :\r\n\r\nPrincipal : Grand fessier\r\n\r\nSecondaires : Ischio-jambiers, érecteurs du rachis, abdominaux (stabilisation)	Installation :\r\n\r\nFixe une corde à la poulie basse (au niveau le plus bas).\r\n\r\nFais face dos à la machine.\r\n\r\nAttrape la corde entre tes jambes, marche un ou deux pas en avant pour mettre la tension.\r\n\r\nPosition de départ :\r\n\r\nPieds écartés largeur des hanches ou légèrement plus.\r\n\r\nGenoux légèrement fléchis.\r\n\r\nBuste penché vers l’avant, charnière de hanche (dos droit, fesses vers l’arrière).\r\n\r\nBras tendus, corde tirée vers l’avant entre les jambes.\r\n\r\nTirage :\r\n\r\nPousse les hanches vers l’avant en contractant fortement les fessiers.\r\n\r\nReviens à une position debout droite, sans hyperextension du dos.\r\n\r\nLes bras suivent naturellement (mais ne tirent pas), la corde reste proche du corps.\r\n\r\nRetour contrôlé :\r\n\r\nReviens lentement en charnière de hanche, en gardant la tension sur les fessiers.\r\n\r\nNe relâche pas complètement la charge pour garder la tension musculaire.\r\n\r\nRépétitions :\r\n\r\n3–4 séries de 12–15 reps, tempo contrôlé	2.5	0	200	DEBUTANT	0	t	f						0		0	0	1	REPETITIONS	https://res.cloudinary.com/dnernoibr/image/upload/v1752757135/basicfit/machines/gifs/machine_f609f1a231f6e025e08bf714b7690a67.gif		
44	2025-07-14 08:42:45.692802+00	2025-07-17 14:59:16.57057+00	t	\N	Calf Raise Machine		Exercice d’isolation qui cible principalement le triceps sural (jumeaux et soléaire), visant l’hypertrophie et la définition des mollets. Réalisable en version debout (standing calf raise), assise (seated calf raise) ou à la presse.\r\n\r\nMuscles travaillés :\r\n\r\nGastrocnémien (jumeaux) – fibre rapide, volume\r\n\r\nSoléaire – fibre lente, endurance (surtout en assis)	Installation :\r\n\r\nPlace l’avant du pied sur la plateforme, talons libres dans le vide.\r\n\r\nPositionne les épaules sous les coussinets, dos droit.\r\n\r\nPosition de départ :\r\n\r\nGenoux légèrement fléchis, poids sur l’avant-pied.\r\n\r\nAbdos gainés, buste stable.\r\n\r\nMontée :\r\n\r\nPousse lentement sur la pointe des pieds, contracte au maximum en haut du mouvement.\r\n\r\nNe verrouille pas les genoux.\r\n\r\nDescente :\r\n\r\nRedescends contrôlé jusqu’à sentir un léger étirement des mollets (talons sous le niveau de la plateforme).\r\n\r\nGarde la tension, ne repose pas complètement.\r\n\r\nRépétitions :\r\n\r\n4–5 séries de 12–20 reps selon l’objectif (plus de reps pour le soléaire en assis).	2.5	0	200	DEBUTANT	0	t	f						0		0	0	1	REPETITIONS	https://res.cloudinary.com/dnernoibr/image/upload/v1752764355/basicfit/machines/gifs/machine_Single-Leg-Standing-Smith-Machine-Calf-Raise.gif		
