4	2025-07-10 19:02:38.953654+00	2025-07-21 16:02:28.676957+00	t	\N	Cable Lateral Raise		Le Cable Lateral Raise est un exercice d’isolation qui cible principalement le deltoïde moyen (faisceau latéral de l’épaule), permettant de construire des épaules plus larges et définies. La poulie ajoute une tension constante tout au long du mouvement, contrairement aux haltères.\r\n\r\nMuscle principal : Deltoïde moyen (faisceau latéral)\r\n\r\nMuscles secondaires : Trapèzes supérieurs (stabilisation), deltoïdes antérieur/postérieur, supra-épineux	Réglage :\r\nFixe la poignée à la poulie basse.\r\nPlace-toi de côté par rapport à la machine.\r\nSaisis la poignée avec le bras opposé à la poulie (la poulie est derrière toi).\r\n\r\nPosition de départ :\r\nPieds largeur hanches, posture droite, abdos engagés.\r\nBras légèrement fléchi (10–15°), croisé légèrement devant la cuisse opposée.\r\nÉpaule basse, pas de tension dans le cou.\r\n\r\nExécution de l'élévation :\r\nLève le bras latéralement en arc de cercle, jusqu’à l’horizontale (épaule hauteur).\r\nGarde l’angle du coude constant tout au long du mouvement.\r\nPause de 1 seconde en haut, ressens la contraction du deltoïde.\r\n\r\nRetour contrôlé :\r\nRedescends lentement le bras à la position de départ.\r\nNe laisse pas le poids retomber ou tirer l’épaule vers le bas.	2.5	5	50	DEBUTANT	0	t	f						0	epaules,isolation,deltoides,cable,debout,debutant	0	0	1	REPETITIONS	https://res.cloudinary.com/dnernoibr/image/upload/v1753113747/basicfit/machines/gifs/machine_OA_CABLE_LAT_RAISE.gif		
