50	2025-07-14 12:26:50.577727+00	2025-07-29 21:22:42.076812+00	t	\N	Seated Triceps Press	Seated Triceps Press	Assis sur un banc avec dossier, tu tiens un haltère à deux mains au-dessus de la tête. Le mouvement consiste à fléchir les coudes pour abaisser l'haltère derrière la tête, puis à tendre les bras pour revenir à la position initiale.	1. Assieds-toi bien droit, dos appuyé, pieds ancrés au sol.\r\n2. Saisis un haltère avec les deux mains, paumes vers le haut en forme de "losange" autour du disque supérieur.\r\n3. Tends les bras au-dessus de la tête (biceps proches des oreilles).\r\n4. Inspire, puis fléchis les coudes lentement pour abaisser l’haltère derrière la tête. Garde les coudes stables et serrés.\r\n5. Stoppe à l’étirement maximal sans perdre la forme.\r\n6. Expire en tendant les bras pour revenir à la position initiale.	2.5	10	80	DEBUTANT	75	t	f						0	triceps,bras,isolation,machine guidée,assise	0	0	5	REPETITIONS	https://res.cloudinary.com/dnernoibr/image/upload/v1752785452/basicfit/machines/gifs/machine_SEAT_DIPS_MC.gif		3-1-z
19	2025-07-10 19:13:03.970414+00	2025-07-29 21:02:06.738814+00	t	\N	Bench Press		Le bench press est un exercice de musculation polyarticulaire qui cible principalement les pectoraux, mais aussi les triceps et les deltoïdes antérieurs. Il se réalise allongé sur un banc plat, en poussant une barre vers le haut à partir de la poitrine.\r\n\r\nMuscles ciblés :\r\n\r\nPrincipal : Pectoraux (grand pectoral)\r\n\r\nSecondaires : Triceps brachial, deltoïdes antérieurs, dentelé antérieur, coraco-brachial	Installation :\r\nAllonge-toi sur le banc, les yeux juste sous la barre.\r\nPieds à plat au sol, légèrement écartés.\r\nDos légèrement cambré, omoplates serrées.\r\nPrise de la barre légèrement plus large que la largeur des épaules (prise pronation).\r\n\r\nDépart :\r\nDécolle la barre du rack (demande un spotter si lourd).\r\nGarde les bras tendus au-dessus de la poitrine.\r\n\r\nDescente :\r\nDescends lentement la barre jusqu’à frôler ou toucher la poitrine (ligne des tétons environ).\r\nContrôle le mouvement, garde les coudes à 45–60° du buste.\r\n\r\nPoussée :\r\nPousse la barre verticalement vers le haut jusqu’à extension complète des bras.\r\nGarde les pieds bien ancrés et le dos stable.	2.5	0	200	DEBUTANT	0	t	f						0		0	0	1	REPETITIONS	https://res.cloudinary.com/dnernoibr/image/upload/v1752820846/basicfit/machines/gifs/machine_SPOTO_BP.gif		3-1-1
40	2025-07-14 08:42:44.917141+00	2025-07-29 21:03:35.078853+00	t	\N	Biceps Curl Machine		Le Biceps Curl Machine est un exercice d'isolation qui cible spécifiquement les biceps brachiaux. Grâce à la machine, le mouvement est guidé, ce qui permet de bien contrôler l'exécution, notamment pour les débutants ou lors d’un travail de finition.\r\n\r\nMuscles ciblés :\r\n\r\nPrincipal : Biceps brachial\r\n\r\nSecondaire : Brachial antérieur, brachio-radial (dans une moindre mesure)	Installation :\r\nAssieds-toi sur la machine, le dos bien droit.\r\nAjuste le siège pour que tes aisselles reposent confortablement sur le pupitre.\r\nSaisis les poignées ou la barre (prise en supination — paumes vers le haut).\r\n\r\nPosition de départ :\r\nLes bras sont presque tendus (légère flexion pour protéger les coudes).\r\nGarde les coudes bien en contact avec le pupitre, sans bouger pendant l'exercice.\r\n\r\nExécution du curl :\r\nFléchis les coudes pour remonter les poignées ou la barre vers tes épaules.\r\nContracte les biceps au maximum en haut du mouvement (sans lever les coudes).\r\n\r\nRetour contrôlé :\r\nRedescends lentement à la position de départ, en gardant la tension dans les biceps.\r\nNe verrouille pas complètement les coudes.	2.5	0	200	DEBUTANT	0	t	f						0		0	0	1	REPETITIONS	https://res.cloudinary.com/dnernoibr/image/upload/v1752751701/basicfit/machines/gifs/machine_b6ea17377640b9bb77068888388b5d0a.gif		2-1-2
8	2025-07-10 19:02:38.977712+00	2025-07-29 21:19:19.311905+00	t	\N	Cable Row		Exercice de tirage horizontal pour le dos, ciblant principalement les lats (grand dorsal), rhomboïdes, et trapèzes moyens, avec implication des biceps.	Position de départ :\r\nAssieds-toi, pieds calés.\r\nPrends la poignée, bras tendus, dos droit, légère inclinaison vers l’avant.\r\n\r\nTirage :\r\nTire la poignée vers l’abdomen (nombril), en ramenant les coudes en arrière.\r\nGarde les épaules basses et le buste fixe.\r\n\r\nRetour :\r\nRelâche lentement les bras en gardant le contrôle.\r\nNe laisse pas les épaules s’enrouler.	2.5	10	120	INTERMEDIAIRE	0	t	f						0	dos,biceps,row,cable,assise,intermediaire	0	0	1	REPETITIONS	https://res.cloudinary.com/dnernoibr/image/upload/v1752760559/basicfit/machines/gifs/machine_close-grip-cable-row.gif		2-1-2
51	2025-07-14 12:26:50.580437+00	2025-07-29 21:23:08.729922+00	t	\N	Dip Assist	Dip Assist	Exercice au poids du corps avec assistance (plateforme ou contrepoids) : tu descends entre deux barres parallèles en fléchissant les bras, puis tu remontes en les tendant.	1. Réglage : choisis le poids d’assistance (plus il est élevé, plus l'exercice est facile).\r\n2. Place les genoux (ou pieds selon modèle) sur la plateforme.\r\n3. Prends les poignées parallèles, bras tendus, épaules basses.\r\n4. Descends lentement en gardant les coudes proches du corps (ou légèrement ouverts si accent sur les pectoraux).\r\n5. Stoppe quand les bras forment un angle de 90° (ou un peu plus si souplesse OK).\r\n6. Pousse avec les triceps pour revenir à la position bras tendus.\r\n7. Garde le buste légèrement penché vers l’avant pour activer les pectoraux, ou droit si tu veux cibler les triceps.	5	20	150	INTERMEDIAIRE	70	t	f						0	triceps,pectoraux,dips,assisté,polyarticulaire	0	0	5	REPETITIONS	https://res.cloudinary.com/dnernoibr/image/upload/v1752820520/basicfit/machines/gifs/machine_ASS_DIP_MC%20%281%29.gif		3-1-2
